Keep the same function signature and compare both head and inputs as order-independent mappings. For example:

export function receiptFresh(before, after) {
  if (before.head !== after.head) return false;
  const a = before.inputs;
  const b = after.inputs;
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length &&
    keys.every(k => Object.prototype.hasOwnProperty.call(b, k) && a[k] === b[k]);
}

