export function tailText(text, budget) {
    if (budget <= 0) return "";

    let start = text.length;
    let bytes = 0;

    while (start > 0) {
        let codePointLength = 1;
        const code = text.codePointAt(start - 1);

        if (code >= 0xDC00 && code <= 0xDFFF && start >= 2) {
            const high = text.charCodeAt(start - 2);
            if (high >= 0xD800 && high <= 0xDBFF) {
                codePointLength = 2;
            }
        }

        const size = Buffer.byteLength(
            text.slice(start - codePointLength, start),
            "utf8"
        );

        if (bytes + size > budget) break;

        bytes += size;
        start -= codePointLength;
    }

    return text.slice(start);
}

