export function tailText(text, budget) {
    if (budget <= 0) return "";
    let end = text.length;
    let bytes = 0;
    while (end > 0) {
        let start = end - 1;
        const ch = text.charCodeAt(start);
        if (ch >= 0xDC00 && ch <= 0xDFFF && start > 0) {
            const prev = text.charCodeAt(start - 1);
            if (prev >= 0xD800 && prev <= 0xDBFF) start--;
        }
        const size = Buffer.byteLength(text.slice(start, end), "utf8");
        if (bytes + size > budget) break;
        bytes += size;
        end = start;
    }
    return text.slice(end);
}

