                state = 'IN_QUOTED';
            } else if (ch === ',') {
                fields.push('');
            } else {
                field += ch;
                state = 'IN_UNQUOTED';
            }
        } else if (state === 'IN_UNQUOTED') {
            if (ch === ',') {
                fields.push(field);
                field = '';
                state = 'FIELD_START';
            } else if (ch === '"') {
                throw new Error('Unexpected quote in unquoted field');
            } else {
                field += ch;
            }
        } else if (state === 'IN_QUOTED') {
            if (ch === '"') {
                if (i + 1 < record.length && record[i + 1] === '"') {
                    field += '"';
                    i += 1;
                } else {
                    state = 'AFTER_QUOTE';
                }
            } else {
                field += ch;
            }
        } else {
            if (ch === ',') {
                fields.push(field);
                field = '';
                state = 'FIELD_START';
            } else {
                throw new Error('Unexpected character after closing quote');
            }
        }
    }

    if (state === 'IN_QUOTED') {
