            if (ch === "\n") {
                emit(pending.slice(start, i));
                start = i + 1;
            } else if (ch === "\r") {
                if (i + 1 < pending.length) {
                    if (pending[i + 1] === "\n") {
                        emit(pending.slice(start, i));
                        start = i + 2;
                        i++;
                    } else {
                        emit(pending.slice(start, i));
                        start = i + 1;
                    }
