export function memoizeReport(load) {
    const values = new Map();
    return (tenant, query) => {
        const labels = [...new Set(query.labels)].sort();
        const normalizedQuery = { labels, archived: query.archived };
        const key = JSON.stringify([tenant, labels, normalizedQuery.archived]);
