export function* take(source, count) {
    if (count === 0) { return; }
    const iterator = source[Symbol.iterator]();
    let exhausted = false;
    let didThrow = false;
    try {
        for (let index = 0; index < count; index += 1) {
            const item = iterator.next();
            if (item.done) { exhausted = true; return; }
            yield item.value;
        }
    } catch (error) {
        didThrow = true;
        throw error;
    } finally {
        if (!exhausted) {
            if (didThrow) {
                try { iterator.return?.(); } catch {}
            } else {
                iterator.return?.();
            }
        }
    }
}

