                parts.some(
                    (part) =>
                        !part ||
                        part === "." ||
                        part === ".." ||
                        part !== part.trim() ||
                        part.endsWith(".") ||
                        deniedDirectories.test(part),
                ) ||
                deniedFile.test(parts.at(-1))
