            !stat.isFile() ||
            stat.nlink !== 1 ||
            files.size >= VERIFY_LIMITS.files ||
            total + stat.size > VERIFY_LIMITS.bytes
        ) {
            throw new Error("Verification requires ordinary unlinked files within 256 files and 8 MiB total.");
        }

