export function tailText(text, budget) {
    if (budget <= 0 || text.length === 0) {
        return "";
    }

    let start = text.length;
    let bytes = 0;

    while (start > 0) {
        const last = text.charCodeAt(start - 1);
        let codePoint = last;
        let width = 1;

        if (last >= 0xDC00 && last <= 0xDFFF && start >= 2) {
            const lead = text.charCodeAt(start - 2);
            if (lead >= 0xD800 && lead <= 0xDBFF) {
                codePoint = ((lead - 0xD800) << 10) + (last - 0xDC00) + 0x10000;
                width = 2;
            }
        }

        const codePointBytes = codePoint <= 0x7F ? 1 : codePoint <= 0x7FF ? 2 : codePoint <= 0xFFFF ? 3 : 4;
        if (bytes + codePointBytes > budget) {
            break;
        }

        bytes += codePointBytes;
        start -= width;
    }

    return text.slice(start);
}

