export function createLines(emit) {
    const decoder = new StringDecoder("utf8");
    let pending = "";
    let ended = false;

    function process(text, final) {
        pending += text;
        let i = 0;
        while (i < pending.length) {
            const ch = pending[i];
            if (ch === "\n") {
                emit(pending.slice(0, i));
                pending = pending.slice(i + 1);
                i = 0;
            } else if (ch === "\r") {
                if (i + 1 < pending.length) {
                    if (pending[i + 1] === "\n") {
                        emit(pending.slice(0, i));
                        pending = pending.slice(i + 2);
                    } else {
                        emit(pending.slice(0, i));
                        pending = pending.slice(i + 1);
                    }
                    i = 0;
                } else if (final) {
                    emit(pending.slice(0, i));
                    pending = pending.slice(i + 1);
                    break;
                } else {
                    break;
                }
            } else {
                i++;
            }
        }
    }

    return {
        write(chunk) {
            if (ended) throw new Error("write after end");
            process(decoder.write(chunk), false);
        },
        end() {
            if (ended) return;
            ended = true;
            process(decoder.end(), true);
            if (pending !== "") {
                emit(pending);
                pending = "";
            }
        },
    };
}

