export function createLines(emit) {
    const decoder = new StringDecoder('utf8');
    const LF = String.fromCharCode(10);
    const CR = String.fromCharCode(13);
    let pending = '';
    let ended = false;

    function process(text) {
        if (!text) return;

        if (pending.endsWith(CR)) {
            if (text[0] === LF) {
                emit(pending.slice(0, -1));
                pending = '';
                text = text.slice(1);
            } else {
                emit(pending.slice(0, -1));
                pending = '';
            }
        }

        for (let i = 0; i < text.length; i++) {
            const ch = text[i];
            if (ch === LF) {
                emit(pending);
                pending = '';
            } else if (ch === CR) {
                if (i + 1 < text.length) {
                    if (text[i + 1] === LF) {
                        emit(pending);
                        pending = '';
                        i++;
                    } else {
                        emit(pending);
                        pending = '';
                    }
                } else {
                    pending += CR;
                }
            } else {
                pending += ch;
            }
        }
    }

    return {
        write(chunk) {
            if (ended) throw new Error('write after end');
            process(decoder.write(chunk));
        },
        end() {
            if (ended) return;
            ended = true;
            process(decoder.end());
            if (pending.endsWith(CR)) {
                emit(pending.slice(0, -1));
                pending = '';
            }
            if (pending !== '') {
                emit(pending);
                pending = '';
            }
        },
    };
}

