import { StringDecoder } from "string_decoder";

export function createLines(emit) {
    const decoder = new StringDecoder("utf8");
    let line = "";
    let pendingCR = false;
    let ended = false;

    const emitLine = () => {
        emit(line);
        line = "";
    };

    const feed = (text) => {
        for (let i = 0; i < text.length; i++) {
            const ch = text[i];

            if (pendingCR) {
                if (ch === "\n") {
                    emitLine();
                    pendingCR = false;
                    continue;
                }

                emitLine();
                pendingCR = false;
            }

            if (ch === "\r") {
                pendingCR = true;
            } else if (ch === "\n") {
                emitLine();
            } else {
                line += ch;
            }
        }
    };

    return {
        write(chunk) {
            if (ended) throw new Error("write after end");
            if (chunk.length === 0) return;
            feed(decoder.write(chunk));
        },
        end() {
            if (ended) return;
            ended = true;
            feed(decoder.end());
            if (pendingCR) {
                emitLine();
                pendingCR = false;
            } else if (line !== "") {
                emit(line);
                line = "";
            }
        },
    };
}

