export function* take(source, count) {
    if (count === 0) { return; }
    const iterator = source[Symbol.iterator]();
    let exhausted = false;
    let closed = false;
    let hasError = false;
    try {
        for (let index = 0; index < count; index += 1) {
            const item = iterator.next();
            if (item.done) { exhausted = true; return; }
            if (index + 1 === count) {
                closed = true;
                iterator.return?.();
            }
            yield item.value;
        }
    } catch (error) {
        hasError = true;
        throw error;
    } finally {
        if (!exhausted && !closed) {
            if (hasError) {
                try { iterator.return?.(); } catch (ignore) {}
            } else {
                iterator.return?.();
            }
        }
    }
}

