export function* take(source, count) {
    if (count === 0) { return; }
    const iterator = source[Symbol.iterator]();
    let exhausted = false;
    let closed = false;
    const close = () => {
        if (!closed && !exhausted) {
            closed = true;
            iterator.return?.();
        }
    };
    try {
        for (let index = 0; index < count; index += 1) {
            const item = iterator.next();
            if (item.done) {
                exhausted = true;
                return;
            }
            if (index === count - 1) {
                close();
            }
            yield item.value;
        }
    } catch (error) {
        try { close(); } catch {}
        throw error;
    } finally {
        close();
    }
}

