            current = captureInputs(root, receipt.inputs);
        } catch {
            return {
                ...structuredClone(receipt),
                status: "stale",
                reason: "Declared input inventory is unavailable or exceeds its bounds.",
            };
        }

        const storedFresh = receipt.before?.digest === receipt.after?.digest;
        const currentFresh =
            storedFresh &&
            current.digest === receipt.before?.digest &&
            current.digest === receipt.after?.digest;
