            receipt.outcome.status === "exited" &&
            receipt.outcome.exitCode === 0 &&
            receipt.outcome.cleanup === "confirmed" &&
            receipt.outcome.reason === "command exited";

        return {
            ...structuredClone(receipt),
            status: !currentFresh ? "stale" : passed ? "passed" : "failed",
            reason: !storedFresh
