export function receiptFresh(before, after) {
    if (before.head !== after.head) {
        return false;
    }

    const beforeInputs = before.inputs;
    const afterInputs = after.inputs;
    const beforePaths = Object.keys(beforeInputs);
    const afterPaths = Object.keys(afterInputs);

    if (beforePaths.length !== afterPaths.length) {
        return false;
    }

    return beforePaths.every((path) => (
        Object.prototype.hasOwnProperty.call(afterInputs, path) &&
        beforeInputs[path] === afterInputs[path]
    ));
}

