export function receiptFresh(before, after) {
    if (before.head !== after.head) return false;

    const beforeInputs = before.inputs;
    const afterInputs = after.inputs;
    const beforePaths = Object.keys(beforeInputs);
    const afterPaths = Object.keys(afterInputs);

    if (beforePaths.length !== afterPaths.length) return false;

    beforePaths.sort();
    afterPaths.sort();

    for (let i = 0; i < beforePaths.length; i++) {
        const path = beforePaths[i];
        if (path !== afterPaths[i]) return false;
        if (beforeInputs[path] !== afterInputs[path]) return false;
    }

    return true;
}

