export function parseRecord(record) {
    const quote = String.fromCharCode(34);
    const fields = [];
    let field = '';
    let i = 0;
    const length = record.length;

    if (length === 0) {
        return [''];
    }

    while (i < length) {
        if (record[i] === quote) {
            i++;
            let closed = false;
            while (i < length) {
                const ch = record[i];
                if (ch === quote) {
                    if (record[i + 1] === quote) {
                        field += quote;
                        i += 2;
                    } else {
                        i++;
                        closed = true;
                        break;
                    }
                } else {
                    field += ch;
                    i++;
                }
            }
            if (!closed) {
                throw new Error('Unterminated quoted field');
            }
            if (i < length && record[i] !== ',') {
                throw new Error('Unexpected character after closing quote');
            }
        } else {
            while (i < length && record[i] !== ',' && record[i] !== quote) {
                field += record[i];
                i++;
            }
            if (i < length && record[i] === quote) {
                throw new Error('Quote in unquoted field');
            }
        }

        if (i < length) {
            fields.push(field);
            field = '';
            i++;
            if (i === length) {
                fields.push('');
                return fields;
            }
        } else {
            fields.push(field);
            return fields;
        }
    }

    return fields;
}

