export async function mapLimit(items, limit, work) {
    if (!Number.isInteger(limit) || limit <= 0) {
        throw new TypeError('limit must be a positive integer');
    }

    const total = items.length;
    if (total === 0) return [];

    const results = new Array(total);
    let nextIndex = 0;
    let active = 0;
    let failed = false;
    let firstError;

    return new Promise((resolve, reject) => {
        const launch = () => {
            while (!failed && active < limit && nextIndex < total) {
                const index = nextIndex;
                nextIndex += 1;
                active += 1;

                let job;
                try {
                    job = work(items[index], index);
                } catch (error) {
                    active -= 1;
                    failed = true;
                    firstError = error;
                    break;
                }

                Promise.resolve(job)
                    .then(
                        (value) => {
                            results[index] = value;
                        },
                        (error) => {
                            if (!failed) {
                                failed = true;
                                firstError = error;
                            }
                        }
                    )
                    .finally(() => {
                        active -= 1;

                        if (failed) {
                            if (active === 0) reject(firstError);
                        } else if (nextIndex === total && active === 0) {
                            resolve(results);
                        } else {
                            launch();
                        }
                    });
            }

            if (failed) {
                if (active === 0) reject(firstError);
            } else if (nextIndex === total && active === 0) {
                resolve(results);
            }
        };

        launch();
    });
}

