                } else {
                    await store.remove(name);
                }
            } catch (rollbackError) {
                rollbackErrors.push(rollbackError);
            }
        }

        if (rollbackErrors.length > 0) {
            throw new AggregateError([error, ...rollbackErrors]);
        }

        throw error;
    }
}

