    function encode(value) {
        if (value === null) return "null";

        const type = typeof value;
        if (type === "string") return "s" + value.length + ":" + value;
        if (type === "number") return "n" + String(value);
        if (type === "boolean") return value ? "b1" : "b0";

        if (Array.isArray(value)) {
            let result = "a" + value.length + "[";
            for (let i = 0; i < value.length; i += 1) {
                const element = encode(value[i]);
                result += element.length + ":" + element;
            }
            return result + "]";
        }

        const keys = Object.keys(value).sort();
        let result = "o" + keys.length + "{";
        for (const key of keys) {
            const encodedKey = "k" + key.length + ":" + key;
            const encodedValue = encode(value[key]);
            result += encodedKey + encodedValue.length + ":" + encodedValue;
