export function createLines(emit) {
    const decoder = new StringDecoder("utf8");
    let line = "";
    let skipLF = false;
    let ended = false;

    function process(text, final = false) {
        let i = 0;

        if (skipLF && text.length > 0) {
            if (text.charCodeAt(0) === 10) {
                i = 1;
            }
            skipLF = false;
        }

        while (i < text.length) {
            const code = text.charCodeAt(i);

            if (code === 10) {
                emit(line);
                line = "";
                i += 1;
            } else if (code === 13) {
                if (i + 1 < text.length) {
                    if (text.charCodeAt(i + 1) === 10) {
                        emit(line);
                        line = "";
                        i += 2;
                    } else {
                        emit(line);
                        line = "";
                        i += 1;
                    }
                } else {
                    emit(line);
                    line = "";
                    skipLF = true;
                    i += 1;
                }
            } else {
                line += text[i];
                i += 1;
            }
        }

        if (final && !skipLF && line.length > 0) {
            emit(line);
            line = "";
        }
    }

    return {
        write(chunk) {
            if (ended) {
                throw new Error("write after end");
            }
            process(decoder.write(chunk));
        },
        end() {
            if (ended) {
                return;
            }
            ended = true;
            process(decoder.end(), true);
        },
    };
}

