export function createLines(emit) {
    const decoder = new TextDecoder("utf-8");
    let pending = "";
    let pendingCR = false;
    let ended = false;

    function emitLine() {
        emit(pending);
        pending = "";
    }

    function process(text) {
        for (let i = 0; i < text.length; i++) {
            const char = text[i];

            if (pendingCR) {
                pendingCR = false;
                if (char === "\n") {
                    emitLine();
                    continue;
                }
                emitLine();
            }

            if (char === "\r") {
                pendingCR = true;
            } else if (char === "\n") {
                emitLine();
            } else {
                pending += char;
            }
        }
    }

    return {
        write(chunk) {
            if (ended) throw new Error("write after end");
            if (!chunk || chunk.length === 0) return;
            process(decoder.decode(chunk, { stream: true }));
        },
        end() {
            if (ended) return;
            ended = true;
            process(decoder.decode());
            if (pendingCR) {
                emitLine();
                pendingCR = false;
            } else if (pending !== "") {
                emitLine();
            }
        },
    };
}

