export function memoizeReport(load) {
    const values = new Map();
    return (tenant, query) => {
        const labels = Array.from(new Set(query.labels)).sort();
        const normalizedQuery = { labels, archived: query.archived };
        const key = JSON.stringify([tenant, labels, query.archived]);
        let entry = values.get(key);
        if (!entry) {
            entry = Promise.resolve()
                .then(() => load(tenant, normalizedQuery))
                .catch((error) => {
