    if (count === 0) { return; }
    const iterator = source[Symbol.iterator]();
    let exhausted = false;
    let sourceThrew = false;
    try {
        for (let index = 0; index < count; index += 1) {
            let item;
            try {
                item = iterator.next();
            } catch (error) {
                sourceThrew = true;
                throw error;
